={{
(() => {
  let text = String($json.technisches_anliegen || '');

  const daten = [
    $json.name,
    $json.telefon,
    $json.telefon_normalisiert,
    $json.email,
    $json.adresse,
    $json.ort
  ].filter(Boolean);

  for (const wert of daten) {
    const sicher = String(wert).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    text = text.replace(new RegExp(sicher, 'gi'), '[ENTFERNT]');
  }

  return text
    .replace(
      /[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi,
      '[E-MAIL ENTFERNT]'
    )
    .replace(
      /(?:\+49|0049|0)[\d\s/()-]{7,}/g,
      '[TELEFON ENTFERNT]'
    )
    .replace(
      /\b(?:mein Name ist|ich heiße)\s+[\p{L}-]+(?:\s+[\p{L}-]+)?/giu,
      '[NAME ENTFERNT]'
    )
    .replace(
      /\b(?:[\p{L}-]+(?:straße|strasse|str\.?|weg|allee|platz|gasse)|(?:[\p{L}-]+\s+){1,3}(?:Straße|Strasse|Str\.?|Weg|Allee|Platz|Gasse))\s+\d+[a-z]?\b/giu,
      '[ADRESSE ENTFERNT]'
    )
    .trim();
})()
}}

