ell|\bevtl\b|unsicher|unklar|weiss (ich )?nicht|keine ahnung|kann ich nicht sagen|nicht sicher|ob (es|da|dort|irgendwo)|schwer zu sagen/;const H=/(nicht|nichts|niemand)\s+(\w+\s+){0,3}(abstellen|abdrehen|zudrehen|absperren|abschalten|ausschalten|stoppen|schliessen|loeschen|erreichen|finden|beheben|stillen|aufhalten)|(abstellen|abdrehen|zudrehen|absperren|abschalten|ausschalten|stoppen|schliessen|loeschen|erreichen|finden|beheben|stillen|aufhalten)\s+(\w+\s+){0,2}nicht\b/;const TR=/(leitung|rohr|boden|waende|wand|decke|keller|stelle|alles|es|hier|dort)\s+(ist |sind |bleibt |war |scheint |wirkt )?(komplett |voellig |ganz |wieder )?(trocken|dicht)\b/;const R={nicht_erwaehnt:0,verneint:1,unklar:2,vorhanden:3};const setze=(art,wert,teil)=>{if(R[wert]>R[Z[art]]){Z[art]=wert;B.push(art+': '+wert+' ('+teil.slice(0,60)+')');} };const bewerte=(teil,tr)=>{if(H.test(teil))return 'vorhanden';if(U.test(teil))return 'unklar';const w=teil.split(' ');const i=teil.slice(0,tr.index).split(' ').length-1;const L=String(tr[0]||'').split(' ').length;for(let j=Math.max(0,i-4);j<Math.min(w.length,i+L+4);j++){if(NEG.test(String(w[j]||'').replace(/[^a-z]/g,'')))return 'verneint';}return 'vorhanden';};for(const teil of T){for(const art of ['gas','wasser','brand','strom']){const tr=I[art].exec(teil);if(tr)setze(art,bewerte(teil,tr),teil);}if(TR.test(teil)&&Z.wasser==='nicht_erwaehnt')setze('wasser','verneint',teil);const d=D.exec(teil);if(d)setze('dringend',bewerte(teil,d),teil);if(V.test(teil))setze('versorgung','vorhanden',teil);} }const arten=['gas','wasser','brand','strom'];const vor=arten.filter(a=>Z[a]==='vorhanden');const notfall=vor.length>0||Z.dringend==='vorhanden'||Z.versorgung==='vorhanden';return{gas:Z.gas,wasser:Z.wasser,brand:Z.brand,strom:Z.strom,dringend:Z.dringend,versorgung:Z.versorgung,notfall:notfall,unklar:arten.some(a=>Z[a]==='unklar'),notfall_art:vor.indexOf('gas')>=0?'gas':(vor.indexOf('wasser')>=0?'wasser':(notfall?'sonstig':'')),begruendung:B};}
