    antwort_text: [basis, freigegeben ? sicherheit : ''].filter(Boolean).join('\n\n'),
    antwort_quelle: grund ? 'Standardantwort' : 'KI',
    pruefgrund: grund || 'KI-Antwort bestanden',
    sicherheitstext_offen: Boolean(sicherheit) && !freigegeben,
    notfall: k.notfall
  };
})()) }}

