// Eingangsprotokoll: nur neue oder hängengebliebene WhatsApp-Nachrichten verarbeiten.
// Übersprungen werden: Nachrichten vor dem Stichtag (whatsapp_verarbeiten_ab), bereits verarbeitete,
// gerade in Bearbeitung befindliche (< 15 Min.) und nach 3 Versuchen aufgegebene Eingänge.
const cfg = $('Betriebskonfiguration').first().json.betrieb;
const stichtag = Date.parse(cfg.whatsapp_verarbeiten_ab || '');
const bekannt = new Map();
for (const item of $('WhatsApp-Eingänge prüfen').all()) {
  if (item.json && item.json.externe_id) bekannt.set(String(item.json.externe_id), item.json);
}
const jetzt = Date.now();
const gesehen = new Set();
const nachrichten = [];
const protokoll = [];
for (const item of $('WhatsApp-API-Daten standardisieren').all()) {
  const sid = String(item.json.message_sid || '');
  if (!sid || gesehen.has(sid)) continue;
  gesehen.add(sid);
  const eingang = Date.parse(item.json.zeitpunkt || '');
  if (!Number.isNaN(stichtag) && !Number.isNaN(eingang) && eingang < stichtag) continue;
  const eintrag = bekannt.get(sid);
  if (eintrag) {
    if (eintrag.status === 'verarbeitet') continue;
    const minuten = (jetzt - Date.parse(eintrag.empfangen_at || '')) / 60000;
    if (eintrag.status === 'empfangen' && minuten < 15) continue;
    if (Number(eintrag.versuche || 0) >= 3) continue;
  }
  nachrichten.push(item.json);
  protokoll.push({
    betrieb_id: cfg.betrieb_id,
    kanal: 'whatsapp',
    externe_id: sid,
    status: 'empfangen',
    empfangen_at: new Date(jetzt).toISOString(),
    versuche: Number(eintrag ? eintrag.versuche || 0 : 0) + 1,
  });
}
if (nachrichten.length === 0) return [];
return [{ json: { protokoll, nachrichten } }];

// Doppelte Vapi-Abschlussberichte erkennen: bereits verarbeitete oder gerade laufende Anrufe nicht erneut verarbeiten.
const cfg = $('Betriebskonfiguration').first().json.betrieb;
const bericht = $('Ist Abschlussbericht?').first().json;
const callId = String((bericht.body && bericht.body.message && bericht.body.message.call && bericht.body.message.call.id) || '').trim();
if (!callId) {
  throw new Error('Vapi-Abschlussbericht ohne Call-ID – Anruf bitte in Vapi manuell prüfen.');
}
const eintrag = $('Vapi-Eingang prüfen').all().map((i) => i.json).find((r) => r && String(r.externe_id) === callId);
if (eintrag) {
  if (eintrag.status === 'verarbeitet') return [];
  const minuten = (Date.now() - Date.parse(eintrag.empfangen_at || '')) / 60000;
  if (eintrag.status === 'empfangen' && minuten < 15) return [];
  if (Number(eintrag.versuche || 0) >= 3) return [];
}
return [{
  json: {
    protokoll: [{
      betrieb_id: cfg.betrieb_id,
      kanal: 'telefon',
      externe_id: callId,
      status: 'empfangen',
      empfangen_at: new Date().toISOString(),
      versuche: Number(eintrag ? eintrag.versuche || 0 : 0) + 1,
    }],
  },
}];

// Kanalneutrale Übergabe an den zentralen Terminassistenten (erst nach erfolgreicher Speicherung).
const b = $json;
const k = $('Bestehende Anfrage?').item.json;
const betrieb = $('Betriebskonfiguration').first().json.betrieb;
const gefahren = $('Kontaktdaten behalten').isExecuted ? ($('Kontaktdaten behalten').item.json.gefahren || null) : null;
return { json: {
  aktion: 'vorschlagen',
  kanal: 'website',
  betrieb,
  kunden_nachricht: '',
  anfrage: {
    anfrage_db_id: b.anfrage_db_id,
    anfrage_id: b.anfrage_id,
    kategorie: b.kategorie,
    dringlichkeit: b.dringlichkeit,
    notfall: b.notfall === true,
    gefahren,
    technisches_anliegen: k.technisches_anliegen || '',
    fehlende_informationen: b.fehlende_informationen,
    adresse: k.adresse || '',
    ort: k.ort || '',
    plz: /^\d{5}$/.test(String(k.plz || '')) ? String(k.plz) : '',
    telefon: b.telefon_normalisiert || k.telefon || ''
  }
} };

// Antwort aus den Formularseiten in eine eindeutige Kundenantwort übersetzen:
// Terminnummer, „Keiner dieser Termine passt“ oder – nach ausgeschöpften Vorschlagsrunden – der Wunschzeitraum.
const E = $('Terminassistent: Eingabe (Website)').first().json;
const x = $input.first().json || {};
if (x.Wunschzeitraum !== undefined) {
  const text = String(x.Wunschzeitraum || '').trim().slice(0, 500);
  return [{ json: Object.assign({}, E, { aktion: 'kundenantwort', kunden_nachricht: text, antwort_vorhanden: text.length > 0, notfall: false }) }];
}
const wahl = String(x.Wunschtermin || x.wunschtermin || '').trim();
const treffer = wahl.match(/^(\d)\)/);
const keiner = wahl === 'Keiner dieser Termine passt';
return [{ json: Object.assign({}, E, { aktion: 'bestaetigen', kunden_nachricht: treffer ? treffer[1] : (keiner ? 'keiner' : ''), antwort_vorhanden: Boolean(treffer) || keiner, notfall: false }) }];

// Mitarbeiterinformation nur für erfolgreich gebuchte, verschobene oder stornierte Termine.
const x = $input.first().json || {};
const c = $('Betriebskonfiguration').first().json.betrieb;
const info = x.mitarbeiter_info;
if (!info || !['gebucht', 'verschoben', 'storniert'].includes(x.ergebnis)) return [];
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
return [{ json: {
  empfaenger: c.mitarbeiter_email,
  betreff: '📅 ' + info.betreff,
  html: '<p style="font-family:Arial,sans-serif">' + esc(info.text).replace(/\n/g, '<br>') + '</p>'
    + '<p style="font-family:Arial,sans-serif;color:#555">Automatisch durch den Terminassistenten verarbeitet. Details stehen in der Aufgabe zur Anfrage.</p>',
  wichtigkeit: 'Normal'
} }];

// Vapi-Tool-Aufruf lesen und absichern. Nur zwei Funktionen sind erlaubt.
const body = $('Vapi-Terminfunktionen').first().json.body || {};
const msg = body.message || {};
const calls = msg.toolCallList || msg.toolCalls || [];
const call = calls[0] || {};
const fn = call.function || {};
let args = fn.arguments;
if (typeof args === 'string') { try { args = JSON.parse(args); } catch (e) { args = {}; } }
args = args && typeof args === 'object' ? args : {};
const callId = String((msg.call && msg.call.id) || '').trim();
const anrufer = String((msg.customer && msg.customer.number) || (msg.call && msg.call.customer && msg.call.customer.number) || '').trim();
let funktion = ['freie_termine_pruefen', 'termin_buchen'].includes(fn.name) && call.id && callId ? fn.name : 'unbekannt';
if (funktion === 'termin_buchen') {
  const startOk = DateTime.fromISO(String(args.termin_start_utc || ''), { zone: 'utc' }).isValid;
  if (args.anrufer_hat_bestaetigt !== true || !startOk) funktion = 'unvollstaendig';
}
return [{ json: { funktion, tool_call_id: String(call.id || ''), call_id: callId, anrufer, args } }];

const t = $('Vapi-Toolaufruf lesen').first().json;
const a = t.args || {};
// Die Anfrage zum Anruf wurde vorher gesucht oder angelegt. Alle Werkzeugaufrufe desselben
// Anrufs arbeiten auf derselben Anfrage, damit keine zweite Anfrage entsteht.
const such = $('Anruf-Anfrage suchen').first().json;
let id = Array.isArray(such.body) && such.body[0] ? such.body[0].id : '';
for (const n of ['Anruf-Anfrage anlegen', 'Anruf-Anfrage nach Konflikt suchen']) {
  if (id || !$(n).isExecuted) continue;
  try { const r = $(n).first().json; id = Array.isArray(r.body) && r.body[0] ? r.body[0].id : ''; } catch (e) { id = ''; }
}
return [{ json: {
  aktion: 'verfuegbarkeit',
  kanal: 'telefon',
  betrieb: $('Betriebskonfiguration').first().json.betrieb,
  kunden_nachricht: '',
  // Bereits genannte, vom Anrufer abgelehnte Termine werden nie erneut angeboten.
  wunsch: { abgelehnte_termine_utc: Array.isArray(a.abgelehnte_termine_utc) ? a.abgelehnte_termine_utc.slice(0, 30).map(String) : [] },
  anfrage: {
    anfrage_db_id: id || null, anfrage_id: t.call_id,
    kategorie: String(a.kategorie || ''), dringlichkeit: String(a.dringlichkeit || 'normal'),
    technisches_anliegen: String(a.anliegen || ''), fehlende_informationen: 'keine',
    adresse: String(a.adresse || ''), plz: String(a.plz || ''), ort: String(a.ort || ''),
    telefon: String(a.telefon || t.anrufer || ''), terminart: String(a.terminart || '')
  }
} }];

// Buchung nur mit gespeicherter Anfrage und ausdrücklich bestätigtem, vom Terminworkflow geliefertem Termin.
const t = $('Vapi-Toolaufruf lesen').first().json;
const a = t.args || {};
const such = $('Anruf-Anfrage suchen').first().json;
let id = Array.isArray(such.body) && such.body[0] ? such.body[0].id : '';
// Neu angelegt oder – bei parallelem Aufruf derselben Anruf-ID – nach dem Datenbankkonflikt wiedergefunden.
for (const n of ['Anruf-Anfrage anlegen', 'Anruf-Anfrage nach Konflikt suchen']) {
  if (id || !$(n).isExecuted) continue;
  try { const r = $(n).first().json; id = Array.isArray(r.body) && r.body[0] ? r.body[0].id : ''; } catch (e) { id = ''; }
}
if (!id) return [{ json: { error: 'Anruf-Anfrage nicht verfügbar' } }];
return [{ json: {
  aktion: 'direkt_buchen',
  kanal: 'telefon',
  betrieb: $('Betriebskonfiguration').first().json.betrieb,
  wunsch: { start_utc: String(a.termin_start_utc || '') },
  kunden_nachricht: '',
  anfrage: {
    anfrage_db_id: id, anfrage_id: t.call_id,
    kategorie: String(a.kategorie || ''), dringlichkeit: String(a.dringlichkeit || 'normal'),
    technisches_anliegen: String(a.anliegen || ''), fehlende_informationen: 'keine',
    adresse: String(a.adresse || ''), plz: String(a.plz || ''), ort: String(a.ort || ''),
    telefon: String(a.telefon || t.anrufer || ''), terminart: String(a.terminart || '')
  }
} }];

// Antwort für Vapi: nur Termine aus dem Terminworkflow, nie erfundene Uhrzeiten.
const t = $('Vapi-Toolaufruf lesen').first().json;
// Das Ergebnis kommt immer vom Terminassistenten. Zwischengeschaltete Speicherschritte
// duerfen die Antwort an Vapi nicht veraendern.
const quelle = ['Terminassistent: Verfügbarkeit (Telefon)', 'Terminassistent: Buchung (Telefon)']
  .find(n => { try { return $(n).isExecuted; } catch (e) { return false; } });
const x = (quelle ? $(quelle).first().json : $input.first().json) || {};
const v = Array.isArray(x.vorschlaege) ? x.vorschlaege : [];
const gr = Array.isArray(x.gruende) ? x.gruende.map(String) : [];
const liste = () => v.map(s => s.nummer + ') ' + s.anzeige + ' [termin_start_utc=' + s.start_utc + ']').join('; ');

// Vier Fälle sauber trennen: fehlende Angaben, wirklich keine freien Termine,
// technischer Fehler und Buchungssperre im Testbetrieb. Fehlende Angaben werden
// nie als "keine Termine frei" dargestellt.
const fehlt = [];
if (gr.some(g => /^PLZ (fehlt|ungültig)/.test(g))) fehlt.push('die fünfstellige Postleitzahl des Einsatzortes');
if (gr.some(g => /^Adresse fehlt/.test(g))) fehlt.push('die vollständige Adresse mit Hausnummer');
if (gr.some(g => /^Telefonnummer fehlt/.test(g))) fehlt.push('die Rückrufnummer');
if (gr.some(g => /^Anliegen unklar/.test(g))) fehlt.push('eine kurze, konkrete Beschreibung des Anliegens');
const offen = gr.find(g => /^Angaben unvollständig:/.test(g));
if (offen) fehlt.push(offen.replace(/^Angaben unvollständig:\s*/, ''));
const keineTermine = gr.some(g => /^Keine freien Termine/.test(g));
const nachfrage = ' Fragen Sie genau diese Angaben nacheinander ab, wiederholen Sie sie zur Bestätigung und rufen Sie freie_termine_pruefen danach erneut auf – mit allen bereits bekannten Angaben. Sagen Sie ausdrücklich nicht, dass keine Termine frei sind.';

let text;
if (t.funktion === 'unbekannt') text = 'Diese Funktion ist nicht verfügbar. Nennen Sie keine Termine; nehmen Sie das Anliegen auf, das Serviceteam meldet sich.';
else if (t.funktion === 'unvollstaendig') text = 'Nicht gebucht. Nennen Sie dem Anrufer zuerst genau einen der gelieferten Termine, holen Sie eine ausdrückliche Bestätigung ein und übergeben Sie termin_start_utc exakt wie geliefert sowie anrufer_hat_bestaetigt = true.';
else if (x.error || !x.ergebnis) text = 'Technischer Fehler: Die Terminfunktion ist gerade nicht erreichbar. Das liegt weder an fehlenden Angaben noch an belegten Terminen. Nennen Sie keine Termine und sagen Sie, dass sich das Serviceteam zur Terminabstimmung meldet.';
else if (x.ergebnis === 'testmodus') text = (t.funktion === 'termin_buchen')
  ? 'Nicht gebucht: Die verbindliche Buchung ist im Testbetrieb gesperrt, es wurde kein Termin gebucht. Es liegt weder an fehlenden Angaben noch an belegten Terminen. Sagen Sie dem Anrufer klar, dass der Termin noch nicht verbindlich ist und das Serviceteam sich zur Bestätigung meldet. Halten Sie den gewünschten Termin in der Gesprächszusammenfassung fest.'
  : 'Terminfunktion im Testbetrieb: verbindliche Buchungen sind gesperrt. Nennen Sie keine Termine; das Serviceteam meldet sich zur Terminabstimmung.';
else if (x.ergebnis === 'verfuegbar' && v.length) text = 'Freie Termine – nennen Sie nur diese, keine anderen Uhrzeiten: ' + liste() + '. Für die Buchung termin_start_utc exakt übernehmen und erst nach ausdrücklicher Bestätigung buchen. Passt keiner, freie_termine_pruefen erneut aufrufen und alle bereits genannten termin_start_utc in abgelehnte_termine_utc übergeben.';
else if ((x.ergebnis === 'gebucht' || x.ergebnis === 'bereits_gebucht') && x.termin) text = 'Termin verbindlich gebucht: ' + x.termin.anzeige + '. Bestätigen Sie dem Anrufer genau diesen Termin. Keine Preise oder Diagnosen nennen.';
else if (x.ergebnis === 'nicht_verfuegbar' && v.length) text = 'Nicht gebucht: der gewünschte Termin ist nicht mehr frei. Alternativ frei: ' + liste() + '. Erst nach neuer ausdrücklicher Bestätigung buchen.';
else if (!x.notfall && fehlt.length) text = 'Noch keine Terminprüfung möglich: Es fehlen noch ' + fehlt.join(' sowie ') + '.' + nachfrage;
else if (x.ergebnis === 'zeitraum_erfragen') text = 'Keine weiteren Termine anbieten. Fragen Sie den Anrufer nach seinem bevorzugten Zeitraum (Wochentage und Uhrzeiten) und nehmen Sie ihn in das Gespräch auf. Das Serviceteam erhält die Anfrage als Aufgabe und meldet sich persönlich.';
else if (!x.notfall && keineTermine) text = 'Angaben vollständig, aber im Planungszeitraum ist kein Termin frei. Das liegt nicht an fehlenden Angaben. Sagen Sie das offen, fragen Sie nach dem bevorzugten Zeitraum und kündigen Sie an, dass das Serviceteam einen passenden Termin persönlich abstimmt.';
else text = 'Keine automatische Terminvergabe möglich' + (x.notfall ? ' (Notfall – folgen Sie der Notfallvorgabe des Betriebs)' : '') + '. Das liegt weder an fehlenden Angaben des Anrufers noch an belegten Terminen. Nennen Sie keine Termine; das Serviceteam meldet sich persönlich.';

return [{ json: { results: [{ toolCallId: t.tool_call_id, result: text }] } }];

// Wurde während des Anrufs bereits ein Termin gebucht, existiert die Anfrage schon: ergänzen statt doppelt anlegen.
const v = $('Vapi-Daten standardisieren').first().json;
const r = $input.first().json || {};
const treffer = r.statusCode === 200 && Array.isArray(r.body) && r.body[0] ? r.body[0].id : '';
return [{ json: Object.assign({}, v, { bestehende_anfrage_db_id: treffer || v.bestehende_anfrage_db_id || '' }) }];

// Vorabpruefung der Betriebseinstellungen vor Inbetriebnahme.
// Laeuft ausschliesslich ueber den Trigger "Pruefung starten".
// Liest nur die zentrale Betriebskonfiguration: keine Kundendaten, keine Nachrichten,
// keine Buchungen, kein Datenbank- und kein Kalenderzugriff.
const b = ($('Betriebskonfiguration').first().json || {}).betrieb || {};
const termin = b.termin || {};
const kalender = termin.kalender || {};
const outlook = kalender.outlook || {};
const gebiet = termin.einsatzgebiet || {};
const t = v => String(v ?? '').trim();

const OK = 'vollstaendig_eingerichtet';
const FEHLT = 'fehlende_einstellung';
const OFFEN = 'integration_nicht_angeschlossen';
const punkte = [];
const p = (bereich, status, befund, hinweis) => punkte.push({ bereich, status, befund, hinweis: hinweis || '' });

const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
p('Betriebskennung', UUID.test(t(b.betrieb_id)) ? OK : FEHLT, t(b.betrieb_id) || 'leer');
p('Firmenname', (t(b.firmenname) && !/bitte anpassen/i.test(t(b.firmenname))) ? OK : FEHLT, t(b.firmenname) || 'leer', 'Demo-Platzhalter ersetzen');
p('Datenbank Supabase', /^https:\/\/[^\s\/]+/.test(t(b.supabase_url)) ? OK : FEHLT, t(b.supabase_url) || 'leer');

const gPlz = (Array.isArray(gebiet.plz) ? gebiet.plz : []).map(x => t(x)).filter(Boolean);
const gOrte = (Array.isArray(gebiet.orte) ? gebiet.orte : []).map(x => t(x)).filter(Boolean);
p('Einsatzgebiet', (gPlz.length || gOrte.length) ? OK : FEHLT,
  'PLZ-Liste: ' + (gPlz.join(', ') || 'keine') + ' | Ortsliste: ' + (gOrte.join(', ') || 'keine'),
  gPlz.length ? 'Geprueft wird die PLZ-Liste als Praefix; die Ortsliste bleibt Rueckfallebene.'
    : (gOrte.length ? 'Nur Ortsliste hinterlegt: greift nur, solange keine PLZ-Liste gesetzt ist.'
      : 'Ohne Einsatzgebiet wird jede Terminanfrage an einen Mitarbeiter uebergeben.'));

p('Betriebsmodus', termin.modus === 'test' ? FEHLT : OK, 'modus = ' + (t(termin.modus) || 'leer'),
  termin.modus === 'test' ? 'Testmodus aktiv: es werden keine echten Termine gebucht.' : '');

[['text_standardantwort', 'Standardantwort'], ['text_standardantwort_notfall', 'Standardantwort Notfall'], ['text_sicherheit_wasser', 'Sicherheitstext Wasser'], ['text_sicherheit_gas', 'Sicherheitstext Gas']].forEach(function (e) {
  const w = t(b[e[0]]);
  p('Text: ' + e[1], (w && !/ENTWURF/i.test(w)) ? OK : FEHLT, w ? (/ENTWURF/i.test(w) ? 'noch als ENTWURF markiert, nicht freigegeben' : 'freigegeben') : 'leer');
});

p('Betriebstelefon', t(b.betrieb_telefon) ? OK : FEHLT, t(b.betrieb_telefon) || 'leer');

const istTestadresse = e => !t(e).includes('@') || /^TEST_/i.test(t(e));
p('E-Mail an Mitarbeiter (Outlook)', istTestadresse(b.mitarbeiter_email) ? OFFEN : OK, t(b.mitarbeiter_email) || 'leer', 'Solange eine Testadresse hinterlegt ist, gilt der Versand als nicht nachgewiesen.');
p('E-Mail Fehleralarm (Outlook)', istTestadresse(b.fehleralarm_email) ? OFFEN : OK, t(b.fehleralarm_email) || 'leer', 'Solange eine Testadresse hinterlegt ist, gilt der Versand als nicht nachgewiesen.');

if (kalender.anbieter === 'outlook') {
  const bereitK = t(outlook.postfach).includes('@') && t(outlook.kalender_id);
  p('Kalender Outlook', bereitK ? OK : FEHLT, 'Postfach: ' + (t(outlook.postfach) || 'leer') + ' | Kalender-ID: ' + (t(outlook.kalender_id) || 'leer'));
} else {
  p('Kalender Outlook', OFFEN, 'anbieter = ' + (t(kalender.anbieter) || 'leer') + ', Ressource = ' + (t(kalender.ressource_id) || 'leer'), 'Testkalender aktiv. Outlook ist nicht angebunden und der Kalenderweg ist nicht getestet.');
}

p('Bereitschaft WhatsApp', t(b.bereitschaft_whatsapp) ? OK : OFFEN, t(b.bereitschaft_whatsapp) || 'leer', 'Notfallalarm an die Bereitschaft ist nicht nachgewiesen.');
p('WhatsApp-Absender', t(b.whatsapp_absender) ? OK : OFFEN, t(b.whatsapp_absender) || 'leer');

const n = s => punkte.filter(x => x.status === s).length;
const label = s => s === OK ? 'OK' : (s === FEHLT ? 'FEHLT' : 'NICHT ANGESCHLOSSEN');
const zeilen = punkte.map(x => '[' + label(x.status) + '] ' + x.bereich + ': ' + x.befund + (x.hinweis ? ' -- ' + x.hinweis : ''));
const bereit = n(FEHLT) === 0 && n(OFFEN) === 0;
const urteil = bereit
  ? 'Vollstaendig eingerichtet.'
  : n(FEHLT) + ' fehlende Einstellung(en), ' + n(OFFEN) + ' nicht angeschlossene Integration(en). Noch nicht betriebsbereit.';

return [{ json: {
  geprueft_am: new Date().toISOString(),
  betrieb: t(b.firmenname),
  betriebsbereit: bereit,
  gesamturteil: urteil,
  anzahl_ok: n(OK),
  anzahl_fehlende_einstellungen: n(FEHLT),
  anzahl_offene_integrationen: n(OFFEN),
  bericht: urteil + '\n\n' + zeilen.join('\n'),
  punkte: punkte
} }];

parameters.jsonBody:
={{ JSON.stringify((() => {
  const t = $('Vapi-Toolaufruf lesen').first().json;
  const a = t.args || {};
  const c = $('Betriebskonfiguration').first().json.betrieb;
  const r = $('Terminassistent: Verfügbarkeit (Telefon)').first().json || {};
  const p = ($('Telefon-Terminprüfung vorbereiten').first().json || {}).anfrage || {};
  const dr = ['niedrig', 'normal', 'hoch', 'notfall'];
  const d = String(a.dringlichkeit || '').toLowerCase();
  const gr = (Array.isArray(r.gruende) && r.gruende.length) ? r.gruende.join('; ') : '';
  const erg = r.ergebnis === 'verfuegbar'
    ? 'Termine angeboten: ' + (Array.isArray(r.vorschlaege) ? r.vorschlaege.map(v => v.anzeige).join('; ') : '')
    : 'Keine automatische Terminvergabe (' + (r.ergebnis || 'unbekannt') + '). Grund: ' + (gr || 'nicht angegeben');
  // Vorhandene Beschreibung uebernehmen, damit spaetere Gespraechsdaten nicht verloren gehen;
  // der Terminpruefungsblock wird immer neu gesetzt statt angehaengt (keine Textkopien).
  let altBasis = '';
  try {
    const zeile = ((($('Anruf-Anfrage suchen').first().json || {}).body || [])[0] || {});
    const altAufgabe = (zeile.aufgaben || []).find(x => x && x.typ === 'anfrage_pruefen') || {};
    altBasis = String(altAufgabe.beschreibung || '').split(/Terminprüfung:/)[0].trim();
  } catch (e) { altBasis = ''; }
  const basis = altBasis || ('Anfrage ' + t.call_id + ' über Telefon: ' + String(a.anliegen || '').slice(0, 900));
  return {
    betrieb_id: c.betrieb_id,
    anfrage_db_id: p.anfrage_db_id,
    typ: 'anfrage_pruefen',
    titel: 'Telefonanfrage (Terminprüfung): ' + (a.kategorie || 'Sonstiges'),
    beschreibung: (basis + String.fromCharCode(10) + 'Terminprüfung: ' + erg).slice(0, 1800),
    prioritaet: dr.includes(d) ? d : 'normal',
    status: 'offen',
    freigabe_erforderlich: true
  };
})()) }}

