}) }];

conditions.leftValue:
={{ (() => {
  // Ein Anruf gilt nur als belegbar leer, wenn Gespraechsprotokoll UND Transkript vorliegen,
  // darin kein Anruferbeitrag steht und auch keine Kundenangabe erfasst wurde. Fehlt eines
  // davon, bleibt es ein ungeklaerter Fall fuer die bestehende Fehlerbehandlung.
  const c = $('Vapi-Call abrufen').first().json || {};
  const q = (c.artifact && Array.isArray(c.artifact.messages)) ? c.artifact.messages : (Array.isArray(c.messages) ? c.messages : null);
  const roh = (c.artifact && typeof c.artifact.transcript === 'string') ? c.artifact.transcript : (typeof c.transcript === 'string' ? c.transcript : null);
  if (!Array.isArray(q) || q.length === 0 || typeof roh !== 'string') return false;
  const rollen = q.map(m => String((m || {}).role || '').toLowerCase());
  if (rollen.some(x => x === 'user' || x === 'customer' || x === 'human')) return false;
  if (rollen.some(x => x === 'tool' || x === 'function' || x.indexOf('tool_call') === 0)) return false;
  const marken = ['user:', 'kunde:', 'customer:'];
  const gesprochen = roh.split(String.fromCharCode(10)).some(zeile => {
    const z = String(zeile).trim().toLowerCase();
    const m = marken.find(x => z.indexOf(x) === 0);
    return Boolean(m) && z.slice(String(m).length).trim() !== '';
  });
  if (gesprochen) return false;
  const felder = ['name', 'telefon', 'ort', 'plz', 'adresse', 'technisches_anliegen'];
  if (felder.some(f => String($json[f] || '').trim() !== '')) return false;
  if ($json.vapi_datenquelle === 'zusammenfassung') return false;
  return true;
})() }}
